// Package hanzoai is the Hanzo API client for Go.
//
// Everything else in this package is generated by scripts/generate.sh from
// hanzoai/cloud's openapi.yaml, at the ref .spec-lock names. This file is not:
// it is the hand-written seam that turns the generated transport into an
// authenticated client.
package hanzoai

import "os"

// DefaultBaseURL is the Hanzo gateway. Every route is <base>/v1/<service>/*.
const DefaultBaseURL = "https://api.hanzo.ai"

// NewConfig returns a Configuration pointed at the Hanzo API and authenticated
// with apiKey. An empty apiKey reads HANZO_API_KEY from the environment; an
// empty HANZO_BASE_URL leaves the base URL at DefaultBaseURL.
//
// The document declares the credential: one `bearer` scheme, required at the
// root, so all but four of its 2479 operations inherit it and the generated
// client carries the code that sends it — client.go reads ContextAccessToken
// and writes `Authorization: Bearer <token>`. That reader takes the token per
// call, off the context.
//
// The credential belongs to the client, not to a call, so this puts it on the
// Configuration once and every operation carries it. Which means there is one
// place to set it: a token in the context as well would be a SECOND
// Authorization header on the same request, because the generated client adds
// both. For a second identity, build a second client — or, to act as one of
// your tenant's subjects, see [APIClient.As].
//
// Use NewConfig when a request needs more than credentials — an org scope, say:
//
//	cfg := hanzoai.NewConfig("")
//	cfg.AddDefaultHeader("X-Org-Id", org)
//	client := hanzoai.NewAPIClient(cfg)
func NewConfig(apiKey string) *Configuration {
	if apiKey == "" {
		apiKey = os.Getenv("HANZO_API_KEY")
	}
	cfg := NewConfiguration()
	if base := os.Getenv("HANZO_BASE_URL"); base != "" {
		cfg.Servers = ServerConfigurations{{URL: base}}
	}
	if apiKey != "" {
		cfg.AddDefaultHeader("Authorization", "Bearer "+apiKey)
	}
	return cfg
}

// NewClient returns a client for the Hanzo API, authenticated with apiKey. An
// empty apiKey reads HANZO_API_KEY from the environment.
//
//	client := hanzoai.NewClient("")
//	keys, _, err := client.KeysAPI.GetKeys(ctx).Execute()
func NewClient(apiKey string) *APIClient {
	return NewAPIClient(NewConfig(apiKey))
}
